# coding: utf-8
from lesson_authoring import entry as E
from author_batch200_root_carbon_a import B
W=[
E('bicarbonate','英 /baɪˈkɑːbənət/；美 /baɪˈkɑːrbənət/','碳酸氢盐；常指小苏打中的碳酸氢钠','把 carbonate 那一家再分细：这里的离子还带着一个氢。','bi- + carbonate；bi- 来自旧化学命名中配比的表示，不是说这个离子有两个碳原子。',B+[['英语 carbonate → bi- + carbonate → bicarbonate','碳酸盐 → 旧命名下的碳酸氢盐']],'碳酸根写 CO₃²⁻，碳酸氢根写 HCO₃⁻，两者都只有一个碳。sodium bicarbonate 就是碳酸氢钠，日常叫 baking soda 小苏打。现代名称 hydrogen carbonate 更直接点出了那个氢。遇到化学名，词根帮你认门，组成仍要看化学式。','sodium bicarbonate；bicarbonate of soda；bicarbonate ions。','baking soda 是小苏打；baking powder 发酵粉通常是含小苏打及其他成分的混合物，配方中不能一概等量互换。',('The label lists sodium bicarbonate as an ingredient.','标签把碳酸氢钠列为一种配料。'),('The teacher compared carbonate and bicarbonate ions on the board.','老师在黑板上比较了碳酸根和碳酸氢根离子。'),sources=['https://en.wiktionary.org/wiki/bicarbonate','https://pubs.rsc.org/ak/content/articlelanding/2020/cp/c9cp06904f']),
E('carbonation','英 /ˌkɑːbəˈneɪʃən/；美 /ˌkɑːrbəˈneɪʃən/','碳酸化；饮料中二氧化碳带来的含气状态','把气体溶进饮料；开盖后，气体又以泡泡的形式跑出来。','carbonate 动词 + -ion，-ate 的词尾变为 -ation，表示过程或状态。',B+[['英语 carbonate → carbonation','使液体含二氧化碳 → 碳酸化、含气状态']],'饮料里的 carbonation 既可说充入二氧化碳的过程，也可说含气程度。汽水放久了变 flat，是它失去了许多溶解的二氧化碳，不是糖消失了。较专业的材料语境也用 carbonation，不能见到它就一定翻成汽水。','natural carbonation；the level of carbonation；lose carbonation。','carbonation 说二氧化碳进入液体或相关反应；carbonization 是炭化，通常指有机材料变成富碳材料，差一个音节也不是同一回事。',('The drink lost most of its carbonation overnight.','这杯饮料放了一夜，大部分气都跑掉了。'),('I prefer sparkling water with gentle carbonation.','我更喜欢气泡温和的气泡水。'),sources=['https://en.wiktionary.org/wiki/carbonation','https://www.merriam-webster.com/dictionary/carbonation']),
E('carbonated','英 /ˈkɑːbəneɪtɪd/；美 /ˈkɑːrbəneɪtɪd/','含二氧化碳气体的；充气的','喝下去有气泡感，因为液体里溶着二氧化碳。','carbonate + -ed，过去分词作形容词；不是 carbon + ate 的过去式。',B+[['英语 carbonate → carbonated','给液体充气 → 已充气的、含气的']],'carbonated water 可以没有糖，也可以没有香味。carbonated 只告诉你饮料含气，不告诉你甜不甜、有没有酒精。因此菜单上的 carbonated 和 still 往往是在问要有气的水还是无气的水。','carbonated water；carbonated beverages；lightly carbonated。','carbonated 是含气；sweetened 是加甜味；两项可以同时有，也可以只占一项。',('Would you like still or carbonated water?','你要无气水还是气泡水？'),('This carbonated drink contains no added sugar.','这款碳酸饮料没有添加糖。'),sources=['https://en.wiktionary.org/wiki/carbonated','https://dictionary.cambridge.org/dictionary/english/carbonated']),
E('carbonic','英 /kɑːˈbɒnɪk/；美 /kɑːrˈbɑːnɪk/','碳的；常用于 carbonic acid 碳酸','碳进入一个化学名称，告诉你这里谈的是哪一种酸。','carbon + -ic，形成形容词；在 carbonic acid 中已经成为固定化学名称的一部分。',B+[['英语 carbon + -ic → carbonic','与碳有关 → 用于碳酸等名称']],'最值得一起记的是 carbonic acid 碳酸。二氧化碳溶入水后，其中一部分与水形成碳酸；饮料有气和略有酸感，因此能够联系起来。不要据此以为一切含碳物质都是酸，或者 carbonic acid 就是一杯可见的气泡。','carbonic acid；a weak solution of carbonic acid。','carbonic 是形容词；carbonate 是碳酸盐或充气的动词。carbonic acid、carbonate、bicarbonate 有化学联系，但名称不可混用。',('The diagram shows how carbonic acid forms in water.','这张图展示了碳酸如何在水中形成。'),('Carbonic acid is a weak acid.','碳酸是一种弱酸。'),sources=['https://en.wiktionary.org/wiki/carbonic','https://pubs.rsc.org/ak/content/articlelanding/2020/cp/c9cp06904f']),
E('carbonara','英 /ˌkɑːbəˈnɑːrə/；美 /ˌkɑːrbəˈnɑːrə/','卡博纳拉意面；蛋、奶酪和腌猪肉等做成的意面酱','菜单上是一盘意面；名字却能一路追到意大利语里与煤、烧炭有关的词。','借自意大利语 carbonara，常见于 alla carbonara；更早接 carbone 煤。具体为什么用这个名称称菜，存在不同说法。',B[:1]+[['意大利 carbone → carbonara／alla carbonara','煤 → 与烧炭有关的称谓；菜名的具体来由有争议'],['英语 carbonara','借入意面及其酱汁的名称']],'词源联系能说明名字里的炭，却不能证明这道菜一定由烧炭工发明。把它想成一道通常用蛋、硬奶酪、腌猪肉和黑胡椒做的意面就够了；不要因餐厅有奶油版本，就把 carbonara 固定解释为任何奶油意面。','spaghetti carbonara；a plate of carbonara；carbonara sauce。','carbonara 是具体菜式或酱汁名；pasta 是意面总称。carbon- 的共同来源不是说菜里添加了炭。',('She ordered spaghetti carbonara and a glass of water.','她点了卡博纳拉意面和一杯水。'),('The chef explained how eggs and cheese create the sauce for carbonara.','厨师解释了蛋和奶酪如何形成卡博纳拉意面的酱汁。'),sources=['https://www.etymonline.com/word/carbonara','https://en.wiktionary.org/wiki/carbonara'])]
